import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"الدستور التكافلي: المبادئ العامة","description":"","frontmatter":{},"headers":[],"relativePath":"ar/40-共生宪法总纲.md","filePath":"ar/40-共生宪法总纲.md"}'),o={name:"ar/40-共生宪法总纲.md"};function d(i,t,n,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="الدستور-التكافلي-المبادئ-العامة" tabindex="-1">الدستور التكافلي: المبادئ العامة <a class="header-anchor" href="#الدستور-التكافلي-المبادئ-العامة" aria-label="Permalink to &quot;الدستور التكافلي: المبادئ العامة&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>40</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>الدستور التكافلي، القانون الأساسي، مساواة عشرة آلاف عرق، الحقوق التكافلية، المبادئ الدستورية</td></tr></tbody></table><h2 id="أولاً-مكانة-الدستور-وسياق-وضعه" tabindex="-1">أولاً: مكانة الدستور وسياق وضعه <a class="header-anchor" href="#أولاً-مكانة-الدستور-وسياق-وضعه" aria-label="Permalink to &quot;أولاً: مكانة الدستور وسياق وضعه&quot;">​</a></h2><p><em>الدستور التكافلي</em> هو القانون الأساسي لحضارة التكافل المرساة داخل كون وانلينغ هنغماو الأصلاني (كون هنغ يوان)، ويتمتع بأعلى قوة قانونية. جميع القوانين واللوائح الإدارية واللوائح المحلية والقواعد الذاتية لا يجوز أن تتعارض مع الدستور؛ وجميع المنظمات والأفراد يجب أن يتخذوا الدستور قاعدة أساسية لأنشطتهم، وعليهم واجب الدفاع عن كرامة الدستور وضمان تنفيذه.</p><p>وُضع الدستور التكافلي عند التأسيس الرسمي لحضارة التكافل المرساة. هدفه الجوهري هو تثبيت، على مستوى القانون الأساسي، اللون الحضاري «مناهضة الافتراس وتعزيز التكافل»، وصياغة الفلسفة الجوهرية لحضارة التكافل المرساة — إعادة حق اختيار المصير والتطور إلى الكائنات جميعاً، الأكثر عملاً الأكثر أجراً، النمو الذاتي والتطور الذاتي، لكل فرد طريق، تقدم عشرة آلاف عرق معاً — في أسمى صيغة قانونية، لمنع عودة الأنظمة الافتراسية.</p><h2 id="ثانياً-المبادئ-الأساسية-للدستور" tabindex="-1">ثانياً: المبادئ الأساسية للدستور <a class="header-anchor" href="#ثانياً-المبادئ-الأساسية-للدستور" aria-label="Permalink to &quot;ثانياً: المبادئ الأساسية للدستور&quot;">​</a></h2><p>يحدد الدستور التكافلي سبعة مبادئ أساسية تشكل حجر الأساس القيمي للنظام القانوني بأكمله:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>مبدأ مساواة عشرة آلاف عرق</td><td>جميع أشكال الحياة، بغض النظر عن العرق أو الزراعة أو الأصل، متساوية أمام القانون</td></tr><tr><td>مبدأ التطور التكافلي</td><td>تطور الفرد لا يجوز أن يكون على حساب حقوق تطور الأفراد الآخرين أو الجماعة</td></tr><tr><td>مبدأ الأكثر عملاً الأكثر أجراً</td><td>توزيع الموارد يستند إلى المساهمة؛ ومعارضة الكسب بلا عمل والاستحواذ الافتراسي</td></tr><tr><td>مبدأ النمو الذاتي والتطور الذاتي</td><td>احترام حق كل كائن في اختيار مسار تطوره باستقلالية؛ ومعارضة الاندماج القسري والتحكم بالفكر</td></tr><tr><td>مبدأ طريق لكل فرد</td><td>على الدولة والحضارة واجب توفير مسار تطور أساسي وضمان موارد لكل كائن</td></tr><tr><td>مبدأ الواقع أساساً</td><td>القانون يتخذ العالم الواقعي الأساس الوحيد الصادق؛ والافتراضات الخيالية لا قوة قانونية لها</td></tr><tr><td>مبدأ الاستدامة</td><td>كل تنمية يجب أن تراعي استدامة أصل الكون؛ ومعارضة استنزاف الموارد جذرياً</td></tr></tbody></table><h2 id="ثالثاً-الحقوق-الأساسية-للمواطنين-جميع-الكائنات" tabindex="-1">ثالثاً: الحقوق الأساسية للمواطنين (جميع الكائنات) <a class="header-anchor" href="#ثالثاً-الحقوق-الأساسية-للمواطنين-جميع-الكائنات" aria-label="Permalink to &quot;ثالثاً: الحقوق الأساسية للمواطنين (جميع الكائنات)&quot;">​</a></h2><p>يمنح الدستور التكافلي جميع أشكال الحياة ذات القدرة على الإدراك داخل كون هنغ يوان الحقوق الأساسية التالية:</p><ol><li><strong>حق اختيار التطور</strong>: لكل كائن الحق في اختيار نظام الزراعة ومسار التطور وطريقة الحياة بحرية؛ ولا يجوز لأي منظمة أو فرد التدخل قسراً.</li><li><strong>حق الحصول على موارد الزراعة</strong>: لكل كائن الحق في الحصول مجاناً على الأساليب الأساسية لثلاثمائة نظام زراعة أصلي، وتلقي دعم موارد الزراعة اللازمة عبر آلية التعاقد المشترك على الإنتاج.</li><li><strong>حق الحماية المتساوية</strong>: يتمتع كل كائن بمعاملة متساوية في تطبيق القانون وتوزيع الموارد والتعليم والعلاج؛ ويُحظر التمييز على أساس العرق أو الزراعة أو الأصل.</li><li><strong>حق المشاركة التكافلية</strong>: لكل كائن الحق في المشاركة في اتخاذ القرارات والإشراف على الشؤون العامة، والتعبير عن الآراء وممارسة الحقوق عبر الشبكة التكافلية.</li><li><strong>حق الحفاظ على الثقافة</strong>: لكل عرق وحضارة الحق في الحفاظ على تقاليدهم الثقافية ولغتهم وكتابتهم وعاداتهم؛ والحضارة التكافلية تحترم التنوع الثقافي.</li><li><strong>حق الإنصاف والطعن</strong>: لكل كائن، عند انتهاك حقوقه، الحق في الحصول على الإنصاف عبر النظام القضائي، وتقديم الشكاوى والادعاءات ضد الأفعال غير القانونية.</li></ol><h2 id="رابعاً-الالتزامات-الأساسية" tabindex="-1">رابعاً: الالتزامات الأساسية <a class="header-anchor" href="#رابعاً-الالتزامات-الأساسية" aria-label="Permalink to &quot;رابعاً: الالتزامات الأساسية&quot;">​</a></h2><p>الحقوق والالتزامات متبادلة؛ يحدد الدستور التكافلي في الوقت نفسه الالتزامات الأساسية لجميع الكائنات:</p><ol><li><strong>التزام الامتثال للدستور والقوانين</strong></li><li><strong>التزام الحفاظ على النظام التكافلي والمصلحة العامة</strong></li><li><strong>التزام المشاركة في العمل والمساهمة وفقاً للقانون</strong> (الوجه المقابل للأكثر عملاً الأكثر أجراً)</li><li><strong>التزام حماية أصل الكون والبيئة الإيكولوجية</strong></li><li><strong>التزام احترام الحقوق المشروعة للكائنات الأخرى</strong></li><li><strong>التزام إرشاد المزارعين المبتدئين في حدود القدرة</strong> (الأساس القانوني لشبكة الموجهين)</li></ol><h2 id="خامساً-الهيكل-المؤسسي-للدولة-الحضارة" tabindex="-1">خامساً: الهيكل المؤسسي للدولة (الحضارة) <a class="header-anchor" href="#خامساً-الهيكل-المؤسسي-للدولة-الحضارة" aria-label="Permalink to &quot;خامساً: الهيكل المؤسسي للدولة (الحضارة)&quot;">​</a></h2><p>يحدد الدستور التكافلي هيكل الحوكمة للحضارة التكافلية، ويطبق آلية «فصل وتوازن السلطات الثلاث» بين المجلس التشريعي للمرساة واللجنة التنفيذية التكافلية ومحكمة التكافل:</p><ul><li><strong>المجلس التشريعي للمرساة</strong>: السلطة العليا، ويتكون من ممثلين لعشرة آلاف عرق بنسب متوازنة، ويمارس السلطة التشريعية وسلطة تقرير الأمور الكبرى</li><li><strong>اللجنة التنفيذية التكافلية</strong>: الجهاز الإداري الأعلى، المسؤول عن تنفيذ الدستور والقوانين والحوكمة اليومية</li><li><strong>محكمة التكافل</strong>: الجهاز القضائي الأعلى، تمارس السلطة القضائية باستقلال، والمسؤولة عن المراجعة الدستورية والنظر في القضايا الكبرى</li></ul><p>بالإضافة إلى ذلك، تُنشأ «لجنة الرقابة للمرساة» كجهاز رقابي مستقل، مسؤول عن الإشراف على جميع أجهزة السلطة، ومنع إساءة استعمال السلطة وعودة الممارسات الافتراسية.</p><h2 id="سادساً-تعديل-الدستور-وضماناته" tabindex="-1">سادساً: تعديل الدستور وضماناته <a class="header-anchor" href="#سادساً-تعديل-الدستور-وضماناته" aria-label="Permalink to &quot;سادساً: تعديل الدستور وضماناته&quot;">​</a></h2><p>لا يسري تعديل الدستور التكافلي إلا بعد موافقة أغلبية الثلثين فأكثر من المجلس التشريعي للمرساة، وموافقة الأغلبية البسيطة في استفتاء عام. تضمن هذه الإجراءات الصارمة استقرار الدستور كقانون أساسي، وتمنع مجموعات المصالح قصيرة الأمد من العبث بأسس الحضارة بسهولة.</p><p>تشمل ضمانات تنفيذ الدستور: نظام المراجعة الدستورية (لمحكمة التكافل الحق في إعلان بطلان القوانين المخالفة للدستور)، ونظام التقاضي الدستوري (يمكن للكائنات رفع الدعاوى مباشرة استناداً إلى الدستور)، ونظام القسم الدستوري (يجب على جميع الموظفين العموميين أداء قسم الولاء للدستور عند تولي مناصبهم).</p><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>الدستور التكافلي</em> هو حجر الأساس القانوني لحضارة التكافل المرساة والإعلان الأعلى لمناهضة الافتراس. يحول «التكافل» من فكرة إلى نظام قانوني قابل للتنفيذ والإنصاف والضمان، ويوفر الإطار القانوني الأساسي لتقدم عشرة آلاف عرق معاً. جميع القوانين القطاعية اللاحقة تُسن استناداً إلى هذا الدستور.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>03-共生文明宪章 (ميثاق الحضارة التكافلية)</li><li>41-共生劳动法 (قانون العمل التكافلي)</li><li>48-司法体系与裁决机制 (النظام القضائي وآليات الفصل)</li><li>49-治理框架与权力制衡 (إطار الحوكمة وتوازن السلطات)</li></ul>',25)])])}const _=a(o,[["render",d]]);export{p as __pageData,_ as default};
